#!/usr/bin/env python3
"""Regenerate core/Runtime/Stages/BuiltInStages.cs from levels/stages/*.lvl.

The core compiles the campaign levels in so tests, the headless runner and a fresh Unity project work
without loading files. Run this after editing a level; a unit test fails if the two drift apart.
"""
from pathlib import Path

root = Path(__file__).resolve().parents[2]
files = sorted((root / "levels" / "stages").glob("*.lvl"))
out = root / "core" / "Runtime" / "Stages" / "BuiltInStages.cs"

lines = [
    "// <auto-generated> by scripts/pc/gen_stages.py from levels/stages/*.lvl. Do not edit by hand. </auto-generated>",
    "using System.Collections.Generic;",
    "",
    "namespace LowObservable.Core.Stages",
    "{",
    "    /// <summary>The campaign's levels, compiled in. Order is campaign order.</summary>",
    "    public static class BuiltInStages",
    "    {",
    "        public static readonly string[] Ids =",
    "        {",
]
lines += [f'            "{f.stem}",' for f in files]
lines += ["        };", "", "        public static readonly Dictionary<string, string> Sources = new Dictionary<string, string>", "        {"]
for f in files:
    text = f.read_text().replace('"', '""')
    lines.append(f'            ["{f.stem}"] = @"{text}",')
lines += [
    "        };",
    "",
    "        public static StageDefinition Load(string id) => StageParser.Parse(id, Sources[id]);",
    "",
    "        public static List<StageDefinition> LoadAll()",
    "        {",
    "            var list = new List<StageDefinition>();",
    "            foreach (var id in Ids) list.Add(Load(id));",
    "            return list;",
    "        }",
    "    }",
    "}",
    "",
]
out.write_text("\n".join(lines))
print(f"Wrote {out.relative_to(root)} ({len(files)} stages)")
